# Look for patterns - find rectangular boxes
def find_boxes(grid, border_value, min_size=1):
    """Find rectangular borders of a given value"""
    boxes = []
    h, w = len(grid), len(grid[0])

    for r in range(h):
        for c in range(w):
            if grid[r][c] == border_value:
                # Check if this could be a top-left corner of a box
                # A top-left corner would have:
                # - bottom-right corner at (r+height, c+width) also being border_value
                # - and forming a rectangular border
                for box_h in range(min_size, min(h-r, w)):
                    for box_w in range(min_size, min(w-c, h)):
                        # Check if this forms a valid box (only border)
                        is_box = True
                        for dr in range(r, r + box_h + 1):
                            for dc in range(c, c + box_w + 1):
                                if grid[dr][dc] == border_value:
                                    # It's on the border or inside
                                    if not (dr == r or dr == r + box_h or dc == c or dc == c + box_w):
                                        is_box = False
                                        break
                            if not is_box:
                                break

                        if is_box:
                            boxes.append((r, c, box_h, box_w, len(grid)))

    return boxes

# The pattern seems to be different - let me look for filled rectangles
def find_filled_rectangles(grid, value, min_size=1):
    """Find rectangles filled with a value (including borders)"""
    rects = []
    h, w = len(grid), len(grid[0])

    for r in range(h):
        for c in range(w):
            if grid[r][c] == value:
                max_h, max_w = 1, 1
                # Expand right
                max_c = c
                for dc in range(c, w):
                    if grid[r][dc] == value:
                        max_c += 1
                    else:
                        break
                max_w = max_c - c

                # Expand down
                max_r = r
                for dr in range(r, h):
                    for dc in range(c, max_c):
                        if grid[dr][dc] != value:
                            max_r = dr - r
                            break
                    if max_r == dr:
                        break
                max_h = max_r + 1

                if max_h >= min_size and max_w >= min_size:
                    if all(grid[dr][dc] == value for dr in range(r, r+max_h) for dc in range(c, c+max_w)):
                        rects.append((r, c, max_h, max_w))

    return rects

