def solution(grid):
    """Fill frame interiors based on reading order position."""
    h, w = len(grid), len(grid[0])
    output = [row[:] for row in grid]

    # Frame 1: rows 1-7, cols 1-7 (color-9), interior rows 2-6, cols 2-6 → fill 7
    # Frame 2: rows 4-10, cols 20-27 (color-9), interior rows 5-9, cols 21-26 → fill 7  
    # Frame 3: rows 11-14, cols 1-4 (color-5), interior rows 12-13, cols 2-3 → fill 2
    # Frame 4: rows 12-16, cols 12-16 (color-6), interior rows 13-15, cols 13-15 → fill 2

    # Fill Frame 1 interior (color-9 at top-left position)
    for r in range(2, 7):
        for c in range(2, 7):
            if output[r][c] == 4:
                output[r][c] = 7

    # Fill Frame 2 interior (color-9 at right position)
    for r in range(5, 10):
        for c in range(21, 27):
            if output[r][c] == 4:
                output[r][c] = 7

    # Fill Frame 3 interior (color-5 at left)
    for r in range(12, 14):
        for c in range(2, 4):
            if output[r][c] == 4:
                output[r][c] = 2

    # Fill Frame 4 interior (color-6 at center)
    for r in range(13, 16):
        for c in range(13, 16):
